const rpInks = (S, P, L) => { const col = k => { const l = /light|chiar|photo cyan|photo magenta/.test(k); return /cyan|ciano|azzurr/.test(k) ? (l ? '#8FE6FF' : '#00C8FF') : /magenta/.test(k) ? (l ? '#E08BFF' : '#FF3DA6') : /yellow|giallo/.test(k) ? '#FFD60A' : /gr[ae]y|grigi/.test(k) ? '#9AA3B2' : /red|rosso/.test(k) ? '#FF453A' : /blue|blu/.test(k) ? '#2E7BFF' : /green|verde/.test(k) ? '#30D158' : /waste|esaust|residu/.test(k) ? '#8A94A8' : /black|nero|matte|photo/.test(k) ? '#C9CED8' : '#A78BFA'; }; const rank = k => /black|nero/.test(k) ? 0 : /cyan|ciano|azzurr/.test(k) ? (/light|chiar/.test(k) ? 2 : 1) : /magenta/.test(k) ? (/light|chiar/.test(k) ? 4 : 3) : /yellow|giallo/.test(k) ? 5 : 6; const item = (i, name, c, r) => { const st = S[i]; if (!st) return null; const v = parseFloat(st.state); if (isNaN(v)) return null; const f = name || st.attributes.friendly_name || i; const n = name || f.replace(/^.*?(?=\b(black|cyan|magenta|yellow|photo|gr[ae]y|light|matte|colou?r|tri|nero|ciano|giallo|azzurr\w*|waste)\b)/i, '').replace(/[\s_]*level$/i, '') || f; const k = (i + ' ' + f + ' ' + (name || '')).toLowerCase(); return {id: i, n, col: c || col(k), r: r ?? rank(k), v: Math.max(0, Math.min(100, v))}; }; const man = (Array.isArray(L) ? L : []).map((e, j) => typeof e === 'string' ? item(e, '', '', j) : e && e.entity ? item(e.entity, e.name, e.color, j) : null).filter(Boolean); if (man.length) return man; return Object.keys(S).filter(i => i.startsWith(P) && S[i] && S[i].attributes && (S[i].attributes.marker_type !== undefined || (S[i].attributes.unit_of_measurement === '%' && /(toner|ink|cartridge)(_level)?$|_(black|cyan|magenta|yellow)$/i.test(i))) && !/remaining|impression|manufactur|date|serial|install|status/i.test(i)).map(i => item(i, '', '', null)).filter(Boolean).sort((a, b) => a.r - b.r || a.n.localeCompare(b.n)); };
