</div>`;
]]]

mini.extra_styles:
.mk { display: flex; flex-direction: column; align-items: center; gap: 1px; width: 100%; }
.ic { width: 66px; height: 36px; overflow: visible; filter: drop-shadow(0 0 4px var(--kc)); }
.nm { font-size: 11px; font-weight: 500; color: #fff; white-space: nowrap; }
.nm .pc { font-size: 10px; font-weight: 700; color: var(--kc); margin-left: 2px; }
.st { font-size: 10px; font-weight: 700; color: var(--kc); white-space: nowrap; letter-spacing: .3px; display: flex; align-items: center; gap: 3px; }
.cr .st { animation: mk_lamp .7s ease-in-out infinite; }
@keyframes mk_lamp { 50% { opacity: .35; } }
@keyframes mk_respiro { 50% { box-shadow: 0 0 16px color-mix(in srgb, var(--kc) 60%, transparent), inset 0 0 0 1px var(--kc); } }
.fi { transform-box: fill-box; transform-origin: 50% 100%; animation: mk_fiamma .9s ease-in-out infinite alternate; }
.fi2 { animation-duration: .65s; animation-delay: .2s; }
@keyframes mk_fiamma { 0% { transform: scale(1, 1) skewX(0); } 50% { transform: scale(.92, 1.1) skewX(-4deg); } 100% { transform: scale(1.04, .94) skewX(3deg); } }
@media (prefers-reduced-motion: reduce) { .mk *, ha-card { animation: none !important; } }

.sp .co { fill: #24213a; stroke: var(--kc); stroke-width: 1.6; }
.sp .fo { fill: #eef2f7; } .sp .fe { fill: #0b0a14; }
.sp .ri { stroke: #8a94a8; stroke-width: 1; }
.sp .usc { transform: translateY(-6px); }
.sp.st1 .usc { animation: sp_usc 2.2s ease-in-out infinite; }
@keyframes sp_usc { 0% { transform: translateY(-8px); } 100% { transform: translateY(2px); } }
.sp .led { fill: var(--kc); animation: mk_lamp 2s ease-in-out infinite; }
.sp .tb { fill: rgba(255,255,255,.10); }
.sp .ib { filter: drop-shadow(0 0 1.5px currentColor); transition: height .6s, y .6s; }
.sp .ib.cr { animation: mk_lamp .9s ease-in-out infinite; }

