// aggiornamento "chirurgico": confronta il nuovo HTML con quello a schermo e cambia solo testi/attributi diversi
window.__morph = (el, html) => {
  const t = document.createElement('template'); t.innerHTML = html;
  const patch = (a, b) => {
    if (a.nodeType !== b.nodeType || a.nodeName !== b.nodeName) { a.replaceWith(b.cloneNode(true)); return; }
    if (a.nodeType === 3 || a.nodeType === 8) { if (a.nodeValue !== b.nodeValue) a.nodeValue = b.nodeValue; return; }
    if (a.nodeType !== 1) return;
    for (const at of [...a.attributes]) if (!b.hasAttribute(at.name)) a.removeAttribute(at.name);
    for (const at of [...b.attributes]) if (a.getAttribute(at.name) !== at.value) a.setAttribute(at.name, at.value);
    figli(a, b);
  };
  const figli = (a, b) => {
    const ac = [...a.childNodes], bc = [...b.childNodes], n = Math.min(ac.length, bc.length);
    for (let i = 0; i < n; i++) patch(ac[i], bc[i]);
