(async () => {
  const ha = document.querySelector('home-assistant');
  const torna = 'rp_printer';
  const apri = id => ha.dispatchEvent(new CustomEvent('ll-custom', {bubbles: true, composed: true,
    detail: {action: 'fire-dom-event', browser_mod: {service: 'browser_mod.popup', data: {popup_card_id: id}}}}));
  try {
    const s = await ha.hass.callWS({type: 'supervisor/api', endpoint: '/ingress/session', method: 'post'});
    document.cookie = 'ingress_session=' + s.session + ';path=/api/hassio_ingress/;SameSite=Strict' + (location.protocol === 'https:' ? ';Secure' : '');
    if (window.__stpSess) clearInterval(window.__stpSess);
    let giri = 0;
    window.__stpSess = setInterval(() => {
      if (++giri > 15) { clearInterval(window.__stpSess); return; }
      ha.hass.callWS({type: 'supervisor/api', endpoint: '/ingress/validate_session', method: 'post', data: {session: s.session}}).catch(() => {});
    }, 240000);
  } catch (e) {}
  if (window.__stpMsg) window.removeEventListener('message', window.__stpMsg);
  window.__stpMsg = ev => { if (ev.origin === location.origin && ev.data && ev.data.remote_print === 'back') apri(torna); };
  window.addEventListener('message', window.__stpMsg);
  apri(torna + '_carica');
})();
